- Testing outages, re-sync, auditability

## Code Example

```javascript
function computeWindowDigest(shares) {
  const crypto = require('crypto');
  const leafs = shares.map(s => crypto.createHash('sha256').update(JSON.stringify(s)).digest('hex'));
  let root = leafs[0] || '';
  for (let i = 1; i < leafs.length; i++) root = crypto.createHash('sha256').update(root + leafs[i]).digest('hex');
  return root;
}
```

